-- שלב 2 (20.10.2026): 5 תשובות FAQ בלי נקודות באמצע פסקה + cta.subtext בלי "פיצוח"/"עליכם".
-- ממתין לאישור שמואל על הנוסח. אחרי אישור: להריץ, ולעדכן את אותו נוסח גם ב-src/components/FAQ.jsx, public/faq.md ו-index.html (JSON-LD).
begin;
update faqs set answer = $q$המחקר והאסטרטגיה לוקחים כשבועיים, ולראות פניות איכותיות זורמות לוקח בין 30 ל-60 יום, תלוי בענף, כי אני בונה איתך לטווח ארוך ולא מבטיח "תוצאות בעוד שבוע".$q$ where id = 'd9faceff-fe5b-4177-a87b-491bbc7a9c3f';
update faqs set answer = $q$מחיר קבוע וסגור שנקבע בשיחת ההיכרות, לפי היקף העבודה: הקמה חד-פעמית + ניהול חודשי (ההשקעה בפרסום נפרדת), בלי חבילות מעורפלות ובלי הפתעות, ותדע בדיוק כמה לפני שמתחילים.$q$ where id = 'b8d0faaa-b3cc-4be5-84a1-ec3088c04e03';
update faqs set answer = $q$רובם מתחילים ב"בוא נריץ קמפיין", ואני מתחיל במחקר על הקהל, המתחרים והמסר, ורק אז בונה קמפיין, משלב כלי AI שחוסכים זמן וכסף, ולוקח מספר מצומצם של לקוחות.$q$ where id = '7cf2ee82-c183-442b-a9ae-c8671d33c365';
update faqs set answer = $q$בגלל זה יש הבטחת ביצוע, ושיהיה ברור, זה לא "חודש ראשון חינם": אם בחודש הניהול הראשון אין פניות, אני ממשיך לנהל בחינם עד שיש, כי הסיכון עליי ולא עליך.$q$ where id = '085c1280-841f-4957-a28e-8008d08f3a24';
update faqs set answer = $q$שניהם: אחרי שסוגרים אסטרטגיה, אני בונה ומפעיל לך את הקמפיינים הממומנים ב-Meta וב-Google ומטפל במסרים ובקריאייטיב, כשותף ביצוע מהמחקר ועד שהקמפיין באוויר.$q$ where id = '7e0b4137-290a-4ec7-b9ea-616a952c357d';
update site_content set value = $q$הקפה עליי, וההחלטה שלך.$q$ where key = 'cta.subtext';
commit;
